"""Explain wake traversal counts and prepare registration semantics."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1457': ('안내원이 명단의 사람들에게 차례로 연락합니다. 특별 입장권을 처리했을 때만 한도를 줄이는 규칙이라면, 연락한 횟수와 사용한 입장권 수는 다릅니다.', '콜백 결과와 EXCLUSIVE 표시를 함께 보고 깨우기 순회를 따라갑니다.', '한도 1에서 N 성공 → E0 결과 0 → E1 성공 → E2 순서를 쓰세요. N과 E0 뒤에는 한도 1, E1 뒤에는 0이라 E2를 살피기 전에 멈춥니다.', ['__wake_up_common은 대기 항목을 하나씩 살펴 콜백을 부르는 핵심 함수입니다. 콜백은 항목별 깨우기 요청을 처리하는 함수입니다. 시작의 lockdep_assert_held는 호출자가 대기열 잠금을 이미 잡았는지 검사하며, 잠금을 대신 잡아 주지는 않습니다.', '빈 목록이면 처음 받은 nr_exclusive를 그대로 반환합니다. 이 숫자는 여기서 남은 exclusive 처리 한도입니다. 호출한 함수에 되돌려 주는 남은 수와 나중에 계산하는 처리 수를 구별하세요.', '각 항목에서는 먼저 flags를 지역 변수에 저장하고 func를 호출합니다. 순회 도구는 다음 항목도 미리 기억합니다. 콜백이 현재 항목을 목록에서 뺄 수 있어서 이후 연결을 따라갈 준비가 필요하기 때문입니다. safe라는 이름이 모든 동시 변경을 잠금 없이 허용한다는 뜻은 아닙니다.', '콜백 결과가 음수이면 즉시 순회를 멈춥니다. 0이면 한도를 줄이지 않고 다음 항목으로 갑니다. 양수라도 EXCLUSIVE 표시가 없다면 한도를 줄이지 않습니다. 양수 결과와 EXCLUSIVE 표시가 함께 있을 때 하나를 뺍니다.', '예를 들어 처음 한도가 1이고 일반 N이 성공해도 한도는 1입니다. 다음 exclusive E0이 0을 돌려줘도 1입니다. E1이 양수를 돌려주면 0이 되어 멈춥니다. 세 콜백을 호출했지만 한도를 소비한 항목은 하나입니다.', '일반적으로 양수는 깨우기 성공을 뜻하지만 사용자 콜백은 이 순회 규칙에 맞춰 특별한 의미를 정할 수도 있습니다. 그러므로 순회가 세는 직접 대상은 콜백 결과와 표시입니다. 모든 호출이 실제로 잠든 태스크 한 명을 깨웠다고 기계적으로 세면 안 됩니다.'], [('일반 항목의 콜백이 양수를 반환하면 exclusive 한도를 줄일까요?', ['네. 양수이면 표시와 관계없이 줄여요', '아니요. EXCLUSIVE 표시도 있어야 줄여요'], '원문은 반환값과 EXCLUSIVE 표시를 함께 검사합니다. 일반 항목의 성공은 그 한도를 소비하지 않으므로 양수만 확인하는 답은 틀립니다.'), ('콜백이 0을 반환하면 한도 1인 순회가 즉시 끝날까요?', ['아니요. 한도를 유지하고 다음 항목을 봐요', '네. 호출 한 번이면 한 장을 쓴 셈이에요'], '0은 한도 감소 조건을 만족하지 않습니다. 호출 횟수와 한도를 소비한 항목 수는 다르므로, 단순히 한 번 호출했다고 멈추지 않습니다.')]), 'os1458': ('접수 창구가 “특별권 두 장을 처리했다”고 보고해도 일반 문의까지 모두 두 건이었다는 뜻은 아닙니다. 무엇을 세어 보고하는 숫자인지 먼저 알아야 합니다.', '깨우기 반환값이 전체 호출 수와 다른 이유를 이해합니다.', '초기 한도 2 → 일반 N 성공: 2 → exclusive E 성공: 1 → 끝. 반환은 2-1=1이라고 계산하세요. 콜백 두 번과 반환 1을 구별하세요.', ['__wake_up_common_lock은 인터럽트 상태를 저장하고 대기열 잠금을 잡습니다. 그 안에서 핵심 순회를 실행해 남은 한도 remaining을 받습니다. 이후 잠금을 풀고 이전 인터럽트 상태를 복원합니다.', '반환식은 nr_exclusive - remaining입니다. 처음 한도에서 남은 한도를 빼면 소비한 한도 수입니다. 일반적인 콜백 규칙에서는 성공한 exclusive 깨우기 수를 뜻하고, 일반 항목 성공 수는 포함하지 않습니다.', '예를 들어 일반 항목 두 개의 콜백이 모두 성공했지만 exclusive 항목은 없었다면 한도가 줄지 않습니다. 초기 1에서 남은 1을 빼 반환은 0입니다. 따라서 반환 0을 아무 콜백도 실행하지 않았다거나 아무도 깨우지 않았다고 읽으면 틀립니다.', 'wake_up_all은 시작 한도를 0으로 넘깁니다. 핵심 순회에서는 양수 exclusive 결과를 만나면 남은 수가 -1, -2처럼 내려가므로 “감소 결과가 0이면 멈춤” 조건으로 종료하지 않습니다. 이 방식으로 양수 한도를 둔 깨우기와 달리 목록을 계속 살핍니다.', '하지만 콜백의 음수 결과는 별도의 중단 조건입니다. all이라는 이름이어도 이 조건을 없애지 않습니다. 사용자 콜백이 음수를 반환하면 뒤의 항목까지 모두 호출하지 않을 수 있습니다.', '또한 반환 수를 실제 공유 자원을 얻은 태스크 수로 사용하면 안 됩니다. 깨운 뒤에도 태스크는 조건과 자원을 다시 확인합니다. 사용자 콜백이 특별한 반환 규칙을 쓰면 한도 소비와 실제 깨움의 관계도 그 콜백에 맞춰 해석해야 합니다.'], [('일반 항목만 성공적으로 깨웠어도 __wake_up이 0을 반환할 수 있을까요?', ['아니요. 언제나 전체 깨운 수를 반환해요', '네. 일반 항목은 exclusive 한도를 줄이지 않아요'], '반환식은 처음 한도에서 남은 한도를 뺍니다. 일반 항목만 처리하면 이 차이는 0일 수 있으므로 전체 콜백 수나 전체 성공 수가 아닙니다.'), ('wake_up_all은 음수 콜백 결과도 무시하고 끝까지 갈까요?', ['아니요. 음수 결과면 순회를 멈춰요', '네. all이면 모든 중단 조건이 없어져요'], '한도 0은 한도에 따른 종료 방식에 영향을 줍니다. ret<0 검사는 그대로 남아 있으므로 all이 사용자 콜백의 중단 계약까지 지우지는 않습니다.')]), 'os1459': ('호출을 기다리려면 먼저 명단에 이름을 올리고, 기다릴 준비를 한 다음 준비됐는지 확인해야 합니다. 이름도 올리지 않고 잠들면 담당자가 나를 놓칠 수 있습니다.', '일반 대기의 등록·상태 설정·조건 확인 순서를 배웁니다.', '항목 링크 초기화 → prepare로 등록·대기 상태 설정 → 조건 확인 → 거짓이면 schedule → 재검사 → finish를 그리세요.', ['prepare_to_wait는 대기할 준비를 하는 함수입니다. 먼저 EXCLUSIVE 표시를 지워 일반 항목으로 만듭니다. 그다음 인터럽트 상태를 저장하고 대기열 잠금을 잡습니다. 아직 이 함수 자체가 schedule로 잠드는 것은 아닙니다.', 'list_empty(&wq_entry->entry)는 이 항목이 다른 항목과 연결되어 있지 않은지 봅니다. 처음에는 링크가 자기 자신을 가리키게 제대로 초기화해야 이 검사가 의미를 가집니다. 아무 값이나 든 링크를 검사해서는 안 됩니다.', '연결되지 않았다면 __add_wait_queue로 등록합니다. 이미 등록되어 있으면 삽입을 건너뜁니다. 기다리다 돌아와 prepare를 또 호출해도 같은 카드를 두 번 명단에 넣지 않으려는 조건입니다.', '등록 여부를 처리한 다음 set_current_state로 현재 태스크의 대기 상태를 설정합니다. 이 함수에 포함된 메모리 배리어가 등록과 나중 조건 확인의 순서를 연결합니다. 단순히 spinlock을 풀었다는 것만으로 필요한 모든 후속 접근 순서를 대신할 수 있다고 생각하면 안 됩니다.', 'prepare가 돌아오면 호출자는 조건을 확인하고, 아직 맞지 않으면 schedule로 실행을 양보합니다. 조건이 맞으면 실제로 잠들지 않고 finish_wait로 정리합니다. 깨어나 다시 시도할 때도 같은 순서를 따릅니다.', '조건을 먼저 딱 한 번 확인하고, 등록도 하지 않은 채 잠드는 방식은 위험합니다. 그 틈에 다른 작업이 조건을 바꾸고 빈 명단을 보고 깨우기를 끝낼 수 있습니다. 등록·상태·조건을 원문의 규칙대로 연결하는 이유입니다.'], [('prepare_to_wait의 새 항목 경로에서는 무엇을 먼저 할까요?', ['대기 상태를 설정한 뒤에 등록해요', '대기열에 등록한 뒤 상태를 설정해요'], '잠금 안에서 list_empty를 검사해 필요한 삽입을 하고, 그다음 set_current_state를 호출합니다. 이 순서를 거꾸로 외우면 원문의 메모리 순서 설명을 놓칩니다.'), ('이미 연결된 항목도 prepare를 부를 때마다 다시 넣을까요?', ['아니요. list_empty일 때만 넣어요', '네. 같은 항목을 매번 하나 더 넣어요'], '등록 여부 조건이 중복 삽입을 막습니다. 한 카드가 여러 개로 복제되는 함수가 아니므로 처음 링크 초기화와 종료 정리도 올바르게 해야 합니다.')]), 'os1460': ('텅 빈 명단에 처음 이름을 적었을 때 “내가 첫 등록자였어”라고 답할 수 있습니다. 같은 사람이 다시 준비를 확인한다고 매번 새 등록자가 되는 것은 아닙니다.', 'exclusive prepare의 반환값이 새 등록 당시의 빈 목록 여부임을 배웁니다.', '빈 목록에 A 첫 호출 → true, A만 남은 상태에서 A 재호출 → false, B 새 호출 → false를 적으세요. false라고 언제나 다른 사람이 있다는 뜻은 아닙니다.', ['prepare_to_wait_exclusive는 한도 처리에 참여하는 대기 항목을 준비합니다. 처음 지역 변수 was_empty를 false로 놓습니다. 이 변수는 이번 호출이 어떤 등록을 했는지 기억하는 결과입니다.', 'EXCLUSIVE 표시를 켜고 대기열 잠금을 잡습니다. 항목의 entry가 비어 있어 아직 연결되지 않았을 때만 새 등록 분기로 들어갑니다. 그때 목록 전체 head가 비었는지를 was_empty에 저장합니다.', '이어서 새 항목을 __add_wait_queue_entry_tail로 목록 끝에 넣습니다. 빈 목록이었다면 결과가 true, 이미 다른 항목이 있었다면 false입니다. 앞쪽 우선 항목보다 무조건 앞으로 끼우는 방식이 아닙니다.', '이미 등록된 항목이면 새 등록 분기를 통째로 건너뜁니다. 따라서 was_empty는 처음 값 false로 남습니다. 예를 들어 목록에 자기 A 하나뿐이어도 A로 재호출하면 false일 수 있습니다. 현재 유일한 사람인지 묻는 조회 함수와 다릅니다.', '등록 뒤에는 set_current_state를 하고 잠금을 풀어 인터럽트 상태를 복원한 다음 was_empty를 반환합니다. 재등록을 생략해도 상태 설정은 수행합니다. 준비가 끝났다는 것이 반드시 이미 잠들었다는 뜻은 아닙니다.', '이 반환값을 이용할 때는 “이번에 새로 넣기 직전에 명단이 비었나”라는 질문으로 읽으세요. 현재 항목 수, 잠금 소유권, 기다리는 조건의 성공 여부를 모두 알려 주는 값이 아닙니다. 이후 조건 검사와 필요할 때의 대기, 종료 정리는 여전히 필요합니다.'], [('자기 항목만 등록된 상태에서 같은 항목으로 재호출하면 반드시 true일까요?', ['네. 한 명이면 언제나 true예요', '아니요. 새 삽입을 안 하면 false로 남아요'], 'was_empty는 새 등록 분기에서만 갱신됩니다. 재호출은 그 분기를 건너뛰므로 한 명이어도 false입니다. 현재 인원수 검사로 해석하면 틀립니다.'), ('새 exclusive 항목은 어디에 연결할까요?', ['목록 맨 뒤에 연결해요', '항상 우선 항목보다 맨 앞으로 넣어요'], '원문은 __add_wait_queue_entry_tail을 호출합니다. tail은 끝을 뜻하므로 우선 항목 앞이라는 답은 틀립니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_360.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
